\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── IEEE S&P Security Theme (GENERIC deep slate + blue accent) ──
\definecolor{primary}{HTML}{1E293B}     % deep slate
\definecolor{secondary}{HTML}{334155}   % slate
\definecolor{accent}{HTML}{2563EB}       % electric blue
\definecolor{bgposter}{HTML}{F1F5F9}     % cool gray background
\definecolor{redbg}{HTML}{FEF2F2}        % warm red tint
\definecolor{bluebg}{HTML}{EFF6FF}       % cool blue tint
\definecolor{darkbg}{HTML}{F0FDFA}      % teal tint
\definecolor{gentlebg}{HTML}{F8FAFC}     % very light slate
\definecolor{textdark}{HTML}{0F172A}
\definecolor{textgray}{HTML}{475569}
\definecolor{stathighlight}{HTML}{DBEAFE}
\definecolor{titlebar}{HTML}{1E293B}

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=20pt, itemsep=4pt, parsep=2pt, topsep=2pt,
  label={\color{accent}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=20pt, itemsep=4pt, parsep=2pt, topsep=2pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Figure+caption macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[2mm]
  {\fontsize{22}{28}\selectfont\color{textgray}\textit{#3}}\vspace{2mm}%
}

% ── Card styles (left accent stripe design) ──
\tcbset{
  redcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=redbg,
    borderline west={5pt}{0pt}{secondary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=redbg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={5pt}{0pt}{accent},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=bluebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.15},
  },
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=darkbg,
    borderline west={5pt}{0pt}{primary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=darkbg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!18!white,
    borderline west={6pt}{0pt}{primary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=5pt, bottomtitle=5pt,
    valign=top, drop shadow={opacity=0.2},
  },
  plaincard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=gentlebg,
    borderline west={5pt}{0pt}{secondary!60},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=gentlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={secondary!40},
    valign=top, drop shadow={opacity=0.12},
  },
}

% ── Pipeline arrow box ──
\newcommand{\pipelinebox}[3]{%
  \tcbox[enhanced, arc=2pt, boxrule=1pt, colback=bluebg,
    borderline={2pt}{0pt}{accent!70},
    left=6pt, right=6pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{22}{28}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=stathighlight,
    toptitle=3pt, bottomtitle=3pt,
    halign=center, valign=center]{%
    \parbox{#1\linewidth}{\centering\vspace{2pt}%
      {\fontsize{22}{28}\selectfont\bfseries\color{primary}#2}\\[2pt]
      {\fontsize{18}{24}\selectfont\color{textgray}#3}\vspace{2pt}%
    }%
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=0mm},
]

% ══ TITLE BAR ══
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=30pt, right=30pt, top=10pt, bottom=8pt,
  halign=center, valign=center,
  drop shadow={opacity=0.3}
]{name=title, column=1, span=2, between=top and row4}{
  {\fontsize{72}{86}\selectfont\bfseries Bot Mitigation at Scale}\\[10pt]
  {\fontsize{48}{58}\selectfont Protecting Scientific Publishing Platforms}\\[8pt]
  {\fontsize{26}{32}\selectfont\color{white!80} IEEE Symposium on Security \& Privacy (S&P)}\\[6pt]
  {\fontsize{22}{28}\selectfont\color{white!60} cloudflare.web.security\ @ 2026}
}

% ══ STAT BANNER ══
\posterbox[
  enhanced, colback=stathighlight, boxrule=0pt, arc=0pt,
  left=10pt, right=10pt, top=4pt, bottom=4pt,
  valign=center, borderline south={3pt}{0pt}{accent!40},
]{name=stats, column=1, span=2, between=row4 and row7}{
  \centering
  \begin{minipage}[c]{0.22\linewidth}\centering
    \fcolorbox{accent!40}{stathighlight}{\parbox{0.86\linewidth}{%
      \centering\vspace{4pt}%
      {\fontsize{58}{70}\selectfont\bfseries\color{accent} 85\%}\\[3pt]
      {\fontsize{20}{26}\selectfont\color{textdark} reduction in scraping}\vspace{4pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.22\linewidth}\centering
    \fcolorbox{accent!40}{stathighlight}{\parbox{0.86\linewidth}{%
      \centering\vspace{4pt}%
      {\fontsize{58}{70}\selectfont\bfseries\color{accent} 99.97\%}\\[3pt]
      {\fontsize{20}{26}\selectfont\color{textdark} uptime maintained}\vspace{4pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.22\linewidth}\centering
    \fcolorbox{accent!40}{stathighlight}{\parbox{0.86\linewidth}{%
      \centering\vspace{4pt}%
      {\fontsize{58}{70}\selectfont\bfseries\color{accent} <2s}\\[3pt]
      {\fontsize{20}{26}\selectfont\color{textdark} user verification}\vspace{4pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.22\linewidth}\centering
    \fcolorbox{accent!40}{stathighlight}{\parbox{0.86\linewidth}{%
      \centering\vspace{4pt}%
      {\fontsize{58}{70}\selectfont\bfseries\color{accent} 0.3\%}\\[3pt]
      {\fontsize{20}{26}\selectfont\color{textdark} legit user friction}\vspace{4pt}%
    }}
  \end{minipage}
}

% ══ THREAT LANDSCAPE (left column) ══
\posterbox[darkcard, title={The Bot Threat Landscape}]
{name=threat, column=1, between=row7 and row12}{
  \fontsize{30}{40}\selectfont
  \begin{itemize}[itemsep=8pt]
    \item \textbf{47\%} of all internet traffic = bots (2024 data)
    \item \textbf{30\%} of bot traffic is malicious
    \item Academic publishers face disproportionate scraping
    \item Targets: peer-reviewed articles, DOIs, datasets
  \end{itemize}
  \vspace{6pt}
  \colorbox{primary!15}{\parbox{0.92\linewidth}{%
    \fontsize{22}{28}\selectfont\color{textdark}
    High-value IP + high traffic = prime bot target
  }}
}

% ══ VERIFICATION PIPELINE (left column, below threat) ══
\posterbox[bluecard, title={Challenge-Based Verification Pipeline}]
{name=pipeline, column=1, between=row12 and row17}{
  \fontsize{28}{36}\selectfont
  \pipelinebox{0.42}{1. Interception}{<50ms CDN edge routing}%
  \pipelinebox{0.42}{2. Threat Scoring}{~100ms TLS, IP, behavior}%
  \pipelinebox{0.42}{3. Challenge}{~500ms JS / CAPTCHA}%
  \pipelinebox{0.42}{4. Verification}{~200ms Ray ID trace}%
  \pipelinebox{0.42}{5. Access Grant}{<50ms origin forward}%
  \vspace{6pt}
  \colorbox{accent!20}{\parbox{0.92\linewidth}{%
    \centering\vspace{3pt}%
    {\fontsize{22}{28}\selectfont\bfseries\color{accent} Total: <2 seconds}\\[2pt]
    {\fontsize{18}{24}\selectfont\color{textgray} for legitimate users}\vspace{3pt}%
  }}
}

% ══ PERFORMANCE METRICS (right column) ══
\posterbox[redcard, title={Performance and Security Outcomes}]
{name=metrics, column=2, between=row7 and row13}{
  \fontsize{30}{40}\selectfont
  \textbf{Before vs. After Deployment:}\\[4pt]
  \begin{tabular}{lcc}
    \rowcolor{primary!15}
    \textbf{Metric} & \textbf{Before} & \textbf{After}\\[2pt]
    Scraping attempts/day & 1.2M & 180K\\
    Origin CPU load & 78\% & 42\%\\
    User complaints/month & 1,200 & 340\\
    Uptime during surges & 98.5\% & \textbf{99.97\%}\\
  \end{tabular}\\[6pt]
  \colorbox{primary!18}{\parbox{0.92\linewidth}{%
    \fontsize{22}{28}\selectfont\color{textdark}
    \textbf{10×} traffic spikes absorbed without service degradation
  }}
}

% ══ TRADE-OFFS (right column, below metrics) ══
\posterbox[plaincard, title={Usability vs. Security Trade-offs}]
{name=tradeoffs, column=2, between=row13 and row17}{
  \fontsize{28}{36}\selectfont
  \begin{itemize}[itemsep=6pt]
    \item \textbf{Accessibility}: WCAG 2.1 compliant challenges
    \item \textbf{Institutional access}: IP allowlisting for universities
    \item \textbf{Transparency}: Clear user messaging during verification
    \item \textbf{Privacy}: Balanced threat detection with clear data practices
  \end{itemize}
}

% ══ KEY TAKEAWAYS (spans both columns at bottom) ══
\posterbox[highlightcard, title={Key Takeaways}]
{name=takeaways, column=1, span=2, between=row17 and bottom}{
  \centering
  \begin{minipage}[c]{0.28\linewidth}\centering
    {\fontsize{32}{40}\selectfont\bfseries\color{white} 1}\\[4pt]
    {\fontsize{24}{32}\selectfont\color{white!90} Bot traffic = half of all requests}\\[2pt]
    {\fontsize{18}{24}\selectfont\color{white!70} to academic publisher sites}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.28\linewidth}\centering
    {\fontsize{32}{40}\selectfont\bfseries\color{white} 2}\\[4pt]
    {\fontsize{24}{32}\selectfont\color{white!90} CDN-edge pipelines block}\\[2pt]
    {\fontsize{18}{24}\selectfont\color{white!70} malicious bots with minimal friction}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.28\linewidth}\centering
    {\fontsize{32}{40}\selectfont\bfseries\color{white} 3}\\[4pt]
    {\fontsize{24}{32}\selectfont\color{white!90} Ray ID tracing enables}\\[2pt]
    {\fontsize{18}{24}\selectfont\color{white!70} continuous optimization}
  \end{minipage}
}

\end{tcbposter}
\end{document}

